            string name="eye-y"+eye.y.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+"-z"+eye.z.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture);var image=ScreenCapture.CaptureScreenshotAsTexture();try
